import React from "react";
import TaskInput from "./TaskInput";
import TaskList from "./TaskList";

const Quadrant = ({ quadrant, tasks, addTask, deleteTask, taskInputs, setTaskInputs }) => {
  const quadrantTitles = {
    1: "Important & Urgent",
    2: "Important & Not Urgent",
    3: "Not Important & Urgent",
    4: "Not Important & Not Urgent",
  };

  return (
    <div className="col-md-3">
      <h3 className="text-center bg-primary text-white p-2">{quadrantTitles[quadrant]}</h3>
      <TaskInput quadrant={quadrant} addTask={addTask} taskInputs={taskInputs} setTaskInputs={setTaskInputs} />
      <TaskList quadrant={quadrant} tasks={tasks} deleteTask={deleteTask} />
    </div>
  );
};

export default Quadrant;
